package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"

	"github.com/satori/go.uuid"
)

// Struct represents the parsed structure definition.
type Struct struct {
	Name      string `json:"name"`
	Fields    []Field `json:"fields"`
}

// Field represents each field within the structure.
type Field struct {
	Type   string `json:"type"`
	Names  []string `json:"names"`
	Doc    string `json:"doc,omitempty"`
}

func main() {
	if len(os.Args) != 3 {
		log.Fatalf("Usage: %s <src_file> <struct_name>", os.Args[0])
	}

	srcFile := os.Args[1]
	structName := os.Args[2]

	fileContent, err := ioutil.ReadFile(srcFile)
	if err != nil {
		log.Fatalf("Failed to read file: %v", err)
	}

	doc, err := parser.ParseFile(token.NewFileSet(), srcFile, fileContent, parser.ParseComments)
	if err != nil {
		log.Fatalf("Failed to parse file: %v", err)
	}

	ast.Inspect(doc, func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.GenDecl:
			if n.Tok == token.TYPE {
				for _, spec := range n.Specs {
					if spec.(*ast.TypeSpec).Name.Name == structName {
						fmt.Println(structName)
						fmt.Println("Type:", structName)
						fmt.Println("Fields:")
						return false // Break out of loop early
					}
				}
			}
		}
		return true
	})

	schema := &Struct{
		Name: structName,
		Fields: []Field{
			{"uuid", []string{uuid.UUID{}.String()}, "Unique identifier"},
			{"id", []string{}, "Primary key"},
			{"name", []string{}, "Name"},
			{"age", []string{}, "Age"},
			{"email", []string{}, "Email"},
		},
	}

	jsonSchema, _ := json.MarshalIndent(schema, "", "  ")
	fmt.Println(string(jsonSchema))

	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), jsonSchema, 0644)
	if err != nil {
		log.Fatalf("Failed to write schema file: %v", err)
	}
}
```

